  function syncOkeyLayoffCandidates(){const s=onlineGame?KANTIN_MATCH.gameState?.state:manager.game?.getStateForPlayer(manager.viewerId),viewer=onlineGame?KANTIN_MATCH.gameState?.seat:manager.viewerId,active=s?.currentPlayer?.id===viewer&&(s.phase==='play'||s.phase==='discard');okeyLayoffCandidates=new Set(active?(s?.layoffCandidateTileIds||[]):[])}
  function syncGroupedOkeyRack(){if(!okeyRackGrouped||okeyRackSlots.length===OKEY_RACK_SLOT_COUNT)return;const s=onlineGame?KANTIN_MATCH.gameState?.state:manager.game?.getStateForPlayer(manager.viewerId);if(!s?.yourHand)return;const suggestions=okeyRackMode==='runs'?s.openingGroups:s.pairGroups,layout=groupedRackOrder([...s.yourHand],okeyRackMode,suggestions);okeyRackOrder=layout.order;okeyRackBreaks=new Set(layout.breaks);okeyRackSlots=rackSlotsFromOrder(layout.order,okeyRackBreaks)}
