  function syncWordRackSlots(state,viewer){const visible=state.yourRack||[],pending=state.currentPlayer?.id===viewer?(state.pending||[]):[],allowed=new Set([...visible,...pending].map(tile=>tile.id));if(wordRackSlots.length!==7)wordRackSlots=(state.yourRackSlots||visible).map(tile=>tile?.id||null).slice(0,7);while(wordRackSlots.length<7)wordRackSlots.push(null);const seen=new Set();for(let i=0;i<wordRackSlots.length;i++){const id=wordRackSlots[i];if(id&&(!allowed.has(id)||seen.has(id)))wordRackSlots[i]=null;else if(id)seen.add(id)}for(const tile of visible)if(!seen.has(tile.id)){const empty=wordRackSlots.indexOf(null);if(empty>=0){wordRackSlots[empty]=tile.id;seen.add(tile.id)}}for(const tile of pending)if(!seen.has(tile.id)){const empty=wordRackSlots.indexOf(null);if(empty>=0){wordRackSlots[empty]=tile.id;seen.add(tile.id)}}return wordRackSlots.map(id=>visible.find(tile=>tile.id===id)||null)}
